        "t_172": "// CATÀLEG DE SOLUCIONS TÈCNIQUES",
        "t_173": "Serveis & Treballs a Mida",
        "t_174": "Feu clic a qualsevol targeta de servei per desplegar el dossier tècnic explicatiu amb especificacions i exemples.",
        "t_175": "// SERVEI 01",
        "t_176": "Vídeo & Spots Cinemàtics",
        "t_177": "Producció audiovisual d´alta fidelitat, anuncis publicitaris, vídeo corporatiu i cinema assistit per IA.",
        "t_178": "DOSSIER TÈCNIC →",
        "t_179": "// SERVEI 02",
        "t_180": "Postproducció & So EBU R128",
        "t_181": "Enginyeria de mescles sonores, masterització per a cinema i plataformes OTT (Netflix/HBO) i àudio forense.",
        "t_182": "// SERVEI 03",
        "t_183": "Directes & Streaming Pro",
        "t_184": "Regidoria multimèdia, emissió broadcast en viu, directes multicàmera i automatització amb OBS/QLab.",
        "t_185": "// SERVEI 04",
        "t_186": "DJ Live & Remescles",
        "t_187": "Sessions de música avançada en directe per a gran format, curació d'identitat sonora i remescles.",
        "t_188": "// SERVEI 05",
        "t_189": "Desenvolupament Web & Web Apps",
        "t_190": "Desenvolupament d'aplicacions web interactives a mida, landing pages d'alt rendiment i integració d'APIs.",
        "t_191": "// SERVEI 06",
        "t_192": "Motion Graphics & Disseny",
        "t_193": "Animació 2D/3D, tractament digital d´imatge, empaquetat gràfic per a esdeveniments i disseny de marca.",
        "t_194": "// SERVEI 07",
        "t_195": "Implantació d'IA Empresarial",
        "t_196": "Automatització de fluxos de treball amb IA Generativa, agents intel·ligents i clonació biomètrica vocal legal.",
        "t_197": "// SERVEI 08",
        "t_198": "Formació & Consultoria",
        "t_199": "Capacitació a mida per a equips en intel·ligència artificial, programari broadcast i direcció de projectes.",
        "t_200": "// PROGRAMARI PROPIETARI AUDITAT DELS REPOSITORIS",
        "t_201": "Ecosistema IA & Prototipat",
        "t_202": "Eines propietàries dissenyades al nostre laboratori intern per optimitzar i automatitzar la postproducció audiovisual i el disseny sonor.",
        "t_203": "v1.0.0 Stable // Electron + React",
        "t_204": "<strong>Aplicació d'Escriptori Modular:</strong>Unifica eines avançades d'edició massiva de vídeo, processament d'imatges i consola DAW per a masterització sonora EBU R128 a local.",
        "t_205": "v1.0.0 Stable // FastAPI + FFmpeg",
        "t_206": "<strong>Pipeline Cinematogràfic Accelerat:</strong>Backend de renderitzat accelerat per a la injecció dinàmica de LUTs professionals (.cube), manipulació de colorimetria en temps real i transcodificació d'alta concurrència.",
        "t_207": "v1.0.0 Stable // LLM Multimodal",
        "t_208": "<strong>Motor de Curació Musical Comercial:</strong>Genera estratègies d'identitat sonora per a retail, locucions neuronals sintètiques i playlists comercials personalitzades.",
        "t_209": "// SHOWCASE VIU DE PRODUCCIONS & REELS",
        "t_210": "Mostra de Produccions Generatives",
        "t_211": "Selecció de projectes audiovisuals. Feu clic sobre qualsevol targeta o el botó<strong>PLAY</strong>per obrir el reproductor amb<strong>àudio complet d'alta fidelitat</strong>.",
        "t_212": "// INSTAGRAM REEL (ACTING IA)",
        "t_213": "[PLAY EN VIU]",
        "t_214": "INSTAGRAM REEL",
        "t_215": "ESCOLTAR ÀUDIO →",
        "t_216": "America'n Job 🇺🇸",
        "t_217": "Acting I.A per @chus_bzn: Estètica 1967 i disseny sonor amb John Williams & Walter Cronkite.",
        "t_218": "FORMAT: REEL 9:16",
        "t_219": "REPRODUIR AMB ÀUDIO →",
        "t_220": "// INSTAGRAM REEL (DORITOS IA)",
        "t_221": "DORITOS A.C 🌋🧀",
        "t_222": "@doritos A.C 🌋🧀: ​​Espot publicitari i innovació generativa I.A per @chus_bzn.",
        "t_223": "// INSTAGRAM REEL (COCA-COLA IA)",
        "t_224": "COCA-COLA CREATIVITY 🥤🔥",
        "t_225": "@cocacola Since 1118 Year: Espot publicitari i animació de concepte de fantasia medieval i guerrers.",
        "t_226": "// SO & RAVE 90S",
        "t_227": "YOUTUBE SHORT",
        "t_228": "VERÍ (BreakBeat Mix)",
        "t_229": "Creació sonor-visual inspirada en ritmes BreakBeat, guitarres elèctriques i estil Rave 90s.",
        "t_230": "FORMAT: ÀUDIO & VÍDEO",
        "t_231": "// CULTURA URBANA BARCELONA",
        "t_232": "BENVINGUTS A LA MEVA CIUTAT 🎭",
        "t_233": "The Random Dusty Clown of Barcelona: Essència de carrer, grafits i art urbà sobre l'asfalt.",
        "t_234": "FORMAT: SHORT IA",
        "t_235": "// CULTURA HIP HOP 1980",
        "t_236": "BRONX 1980",
        "t_237": "Homenatge a les arrels del Hip Hop al Bronx 1980: radiocassettes a l'espatlla i ritmes de TR808.",
        "t_238": "FORMAT: SHORT RAP",
        "t_239": "// INSTAGRAM REEL (GORILLA & DANCE)",
        "t_240": "KILLA — Deus Ex Machina 🎶🔥",
        "t_241": "KILLA Deus ex Machina: Producció generativa amb noies, goril·les i marxandatge KILLA.",
        "t_242": "// INSTAGRAM REEL (NIKE IA)",
        "t_243": "NIKE WEREWOLF 🐺",
        "t_244": "@nike Werewolf 🐺: Espot publicitari i animació de concepte esportiu/fantasia generatiu.",
        "t_245": "// AUDITORIA PROFESSIONAL DE SOLVÈNCIA & CURRÍCULUM INDUSTRIAL",
        "t_246": "Perfil & Trajectòria Auditada",
        "t_247": "Més de 33 anys d'ofici continu en infraestructures crítiques de cinema, televisió de màxima audiència (Cròniques Marcianes a Gestmusic Endemol, TV3, TVE1) i l'avantguarda de l'enginyeria assistida per Intel·ligència Artificial a Barcelona.",
        "t_248": "// MANIFEST INDUSTRIAL CHUS BZN",
        "t_249": "<strong>CHUS BZN</strong>uneix en un perfil únic tres dècades d'història viva de la cultura i l'enginyeria audiovisual a Espanya: des de registrar amb<strong>BZN MCs</strong>el primer LP de Rap editat íntegrament al país, fins a cofundar l'escena de música avançada participant a la primera9</strong>.",
        "t_250": "Amb més de<strong>33 anys de trajectòria professional auditada</strong>en infraestructures de nivell crític, ha exercit la direcció tècnica a<strong>Kombat Jam</strong>(Razzmatazz), 16 anys en plantilla titular de Gestmusic Endemol (<em>Crónicas Marcianas _T5 doblatge per a<strong>Netflix, HBO, Amazon Prime i Sony Pictures</strong>.",
        "t_251": "Totes les solucions tenen blindatge legal i ètica algorítmica garantida sota el protocol europeu<strong>EU AI Act</strong>i l'empara d'entitats de drets (SGAE, AISGE, AEDYP, AIE).",
        "t_252": "ADREÇA DE SISTEMES AUDIOVISUALS & INTEGRACIÓ IA",
        "t_253": "// HISTORIAL DE PROJECTES & PRODUCCIONS",
        "t_254": "Timeline Industrial de 33 Anys",
        "t_255": "Productor Senior & IA Specialist",
        "t_256": "Actuara12 (Estudi & Laboratori Propietari)",
        "t_257": "Lideratge tècnic en produccions cinematogràfiques assistides per IA, control CCU i disseny de programari propietari (Studio Pro Suite, Cine Station Pro).",
        "t_258": "Arquitectura de solucions i consultoria tecnològica d´alt nivell per al sector creatiu i corporatiu audiovisual de Barcelona.",
        "t_259": "Dissenyador de So & Muntador",
        "t_260": "Disseny sonor per a \"Dinàmiks\" (TV3) i muntatge musical per a formats d'entreteniment de màxima audiència nacional com a \"Joc de Nens\" (TVE1) amb Javier Sardà.",
        "t_261": "Doblatge i postproducció de llargmetratges cinematogràfics (trilogia El Senyor dels Anells) i sèries de televisió (American Horror Story, CSI) per a Netflix, HBO, Amazon Prime i Sony Pictures.",
        "t_262": "Direcció tècnica general de les primeres batalles professionals de freestyle organitzades a sales de referència nacional com Razzmatazz. Coordinació de filmació multimèdia.",
        "t_263": "1990 - 2006 (16 Anys Titular)",
        "t_264": "Muntador Musical & So Directe",
        "t_265": "Control de so directe i efectes durant les 8 temporades consecutives de \"Crónicas Marcianas\", el programa líder històric de televisió a Espanya.",
        "t_266": "Operació amb tecnologia analògica industrial pura: sistemes de 35mm, gravadors multipista de cinta oberta i codi de temps analògic.",
        "t_267": "// ACREDITACIÓ OFICIAL GENERALITAT DE CATALUNYA",
        "t_268": "Qualificacions FPCAT (14 Unitats de Competència)",
