        "t_325": "[ SYS_LOG: BROADCAST_LINK_ESTABLISHED ]",
        "t_326": "<span class=\"font-headline text-3xl tracking-tight text-signal-red group-hover:scale-105 transition-transform\">CHUS BZN</span><span class=\"hidden sm:inline-block font-mono text-[10px] text-white/50 tracking-widest uppercase border-l border-white/20 pl-3\">PROFILE & AUDITED CAREER</span>",
        "t_327": "PROFESSIONAL SOLVENCY AUDIT",
        "t_328": "CHUS BZN //<br/><span class=\"text-signal-red\">AUDIT & INDUSTRIAL TRAJECTORY</span>",
        "t_329": "<strong>CHUS BZN</strong>has a history of more than 33 years leading the architecture of audiovisual systems, broadcast sound and development of Artificial Intelligence for the main television networks, production companies and global streaming platforms.",
        "t_330": "33+ Years of Audited Solvency",
        "t_331": "FPCAT Level 3 Official Accreditation",
        "t_332": "Partner SGAE / AISGE / AEDYP / AIE",
        "t_333": "// PROPRIETARY SOFTWARE & CASE STUDIES",
        "t_334": "Modular desktop ecosystem for advanced video editing, massive image processing and DAW mastering console.",
        "t_335": "Accelerated cinematic pipeline for dynamic injection of professional LUTs (.cube), real-time colorimetry and high-efficiency transcoding.",
        "t_336": "AI-assisted music curation engine for sound identity strategies, neural voiceovers and commercial playlists.",
        "t_337": "Deployment of a comprehensive hybrid workflow where AI acts as an acceleration vector in the generation of dynamic visual environments, conceptual character design and script continuity optimized for mass distribution.",
        "t_338": "Forensic audio stream for training and legitimate neural cloning of voice from analog tapes and historical masters. Strict compliance with the EU AI Act and shielding with AISGE.",
        "t_339": "// HISTORY OF PROJECTS & PRODUCTIONS (1987 - PRESENT)",
        "t_340": "33 Year Industrial History",
        "t_341": "Actuara12 (Laboratory & Studio Owner)",
        "t_342": "Technical leadership in corporate events, film productions and development of solutions based on Artificial Intelligence.",
        "t_343": "Solutions architecture and high-level technological consulting for the creative and corporate sector of Barcelona.",
        "t_344": "Dubbing and post-production of feature films (The Lord of the Rings trilogy) and television series (American Horror Story, CSI) for Netflix, HBO and Sony Pictures.",
        "t_345": "Operation with industrial analog technology: 35mm systems, open tape multitrack recorders and analog time code.",
        "t_346": "// ETHICAL FRAMEWORK AND LEGAL SECURITY",
        "t_347": "Compliance & Rights Management",
        "t_348": "Protection of copyright and musical compositions.",
        "t_349": "Protection of interpretations and vocal biometric sovereignty.",
        "t_350": "Association of DJs and Electronic Music Producers.",
        "t_351": "Intellectual property management of performing artists.",
        "t_352": "© 2026 CHUS BZN // AUDITED TRAINER AND TECHNICAL SOLVENCY",
        "t_cta_quote": "ORDER 24H",
        "t_form_sub": "Submit your project details. Guaranteed response within 24 business hours.",
        "t_form_title": "Request Quote / Consulting",
        "t_hero_badge": "SYS_STATUS: OPERATIONAL // FPCAT NVL3 CERTIFICATE",
