        "t_hero_btn_quote": "REQUEST A QUOTE",
        "t_hero_sub": "Strategic fusion between analog sound engineering and the cutting edge of Generative AI. Three decades leading critical infrastructures in film, TV and urban environments.",
        "t_meth_p1": "CHUS BZN is a pioneering audiovisual agency and collective in Barcelona in the creation and development of custom audiovisual and technological projects.",
        "t_meth_p2": "We specialize in the creation, integration, development, automation and implementation of Artificial Intelligence in businesses or companies, operating under strict compliance with European regulations (EU AI Act).",
        "t_meth_title": "Hybrid Methodology & Senior Collective",
        "t_service_design_code": "// DOSSIER 06 - MOTION GRAPHICS & GRAPHIC DESIGN",
        "t_service_design_desc": "Creation of 2D/3D animated visual elements, bumpers for television channels, graphic continuity packages for live broadcasts and brand design.",
        "t_service_design_specs": "<strong>Commercial Solution & Deliverables:</strong><br/>• Advanced animations in After Effects and Blender.<br/>• High resolution photographic and graphic composition.<br/>•<strong>Client application:</strong>High-impact corporate image, promotions and graphics for events.",
        "t_service_design_title": "Motion Graphics & Visual Identity",
        "t_service_dj_code": "// DOSSIER 04 - DJ SESSIONS, LIVE PERFORMANCE & REMIXES",
        "t_service_dj_desc": "Direction and execution of advanced music sessions for festivals, corporate macro events and sound identity of commercial venues.",
        "t_service_dj_specs": "<strong>Commercial Solution & Deliverables:</strong><br/>• Operation with high-end Pioneer professional hardware (DDJ1000 / Rekordbox).<br/>• Room acoustic study and exclusive studio remixes adapted to the profile of the event.<br/>•<strong>Client application:</strong>Large format events, brand conventions and record production.",
        "t_service_dj_title": "DJ Live Performance & Music Production",
        "t_service_formacion_code": "// DOSSIER 08 - TRAINING & TECHNOLOGICAL CONSULTING",
        "t_service_formacion_desc": "Tailored training for production teams, television production companies and companies in emerging AI tools and audiovisual workflows.",
        "t_service_formacion_specs": "<strong>Commercial Solution & Deliverables:</strong><br/>• Intensive Vibe Coding programs, Prompting for video and AI tools.<br/>• In-person or remote technological audit to optimize workflows.<br/>•<strong>Client application:</strong>Rapid digital transformation of human teams and direct increase in productivity.",
        "t_service_formacion_title": "Training & Technological Consulting",
        "t_service_ia_code": "// DOSSIER 07 - IMPLEMENTATION OF BUSINESS AI",
        "t_service_ia_desc": "Strategic integration of Generative Artificial Intelligence, autonomous agents for companies and legal vocal biometric cloning under European regulations.",
        "t_service_ia_specs": "<strong>Commercial Solution & Deliverables:</strong><br/>• Shielding and compliance with the European EU AI Act protocol and voice rights.<br/>• Connection of multimodal models (Claude, ChatGPT, Qwen, DeepSeek) in the company's infrastructure.<br/>•<strong>Customer application:</strong>Massive reduction in operating costs, automated service and content generation in seconds.",
        "t_service_ia_title": "Implementation & Automation of AI in Companies",
        "t_service_sonido_code": "// DOSSIER 02 - POSTPRODUCTION & SOUND EBU R128",
        "t_service_sonido_desc": "Sound mixing engineering, approved sound for public/private television (TV3, TVE1) and international streaming OTT platforms (Netflix, HBO, Amazon Prime).",
        "t_service_sonido_specs": "<strong>Commercial Solution & Deliverables:</strong><br/>• Rigorous volume control (-23 LUFS) under the international standard EBU R128, avoiding emission rejections.<br/>• Forensic spectral cleaning and restoration with iZotope RX11 and SpectraLayers Pro.<br/>•<strong>Client application:</strong>Movies, dubbing series, advertising and premium podcasts.",
        "t_service_sonido_title": "Sound Post Production & Mastering EBU R128",
        "t_service_streaming_code": "// DOSSIER 03 - LIVE, STREAMING & 360° COVERAGE",
        "t_service_streaming_desc": "Technical architecture of audiovisual signal in real time for multinational conventions, sporting events, shows and simultaneous broadcasts on social networks.",
        "t_service_streaming_specs": "<strong>Commercial Solution & Deliverables:</strong><br/>• Automation of multimedia management through OBS Studio, QLab and physical video mixers.<br/>• CCU control of exposure and color adjustment in real time.<br/>•<strong>Customer application:</strong>360° coverage without latency, highly available corporate streaming and uninterrupted broadcast guarantee.",
        "t_service_streaming_title": "Live, Streaming & 360° Broadcast Coverage",
        "t_service_video_code": "// DOSSIER 01 - VIDEO & CINEMATIC SPOTS",
        "t_service_video_desc": "CHUS BZN designs and executes high-level advertising productions, spots for television and corporate brands, multi-camera filming on set and film technical direction assisted by Artificial Intelligence.",
        "t_service_video_specs": "<strong>Commercial Solution & Deliverables:</strong><br/>• Mastering in 4K/8K resolution with ACES color space and proprietary high-fidelity LUTs (.cube).<br/>• Reduction of up to 60% in prevision times and generation of complex plans using ComfyUI & Wan 2.1.<br/>•<strong>Application for the client:</strong>Massive advertising campaigns, video clips and feature films with international film broadcast standards.",
        "t_service_video_title": "Video Production & Cinematic Spots",
        "t_service_web_code": "// DOSSIER 05 - WEB DEVELOPMENT & CUSTOM WEB APPS",
        "t_service_web_desc": "Programming of custom interactive web applications, high-performance SaaS platforms, commercial landing pages and integration of Artificial Intelligence API gateways.",
        "t_service_web_specs": "<strong>Commercial Solution & Deliverables:</strong><br/>• Clean code in HTML5/JS/FastAPI/Electron optimized for maximum loading speed (FCP < 0.8s).<br/>• Responsive design adapted to all mobile devices and desktops.<br/>•<strong>Client application:</strong>Digital point of sale, business process automation and impactful corporate web presence.",
        "t_service_web_title": "Web Development & Interactive Applications",
        "t_srv1_desc": "Spots, corporate, multi-camera and AI-assisted cinema.",
