        "t_169": "<div class=\"flex items-center justify-between\"><div class=\"p-3 bg-signal-red/20 text-signal-red rounded-lg group-hover:bg-signal-red group-hover:text-white transition-colors\"><svg class=\"w-8 h-8\" fill=\"currentColor\" viewbox=\"0 0 24 24\"><path d=\"M1.175 12.225c-.05 0-.096.038-.104.092L.008 18.72c-.008.06.034.112.094.112h1.177c.056 0 .103-.045.103-.103l.094-6.41c.008-.057-.038-.104-.094-.104H1.175zm2.095-1.472c-.056 0-.103.045-.103.103l-.297 7.76c-.008.057.038.104.094.104h1.186c.056 0 .103-.045.103-.103l.297-7.76c.008-.057-.038-.104-.094-.104H3.27zm2.112-1.074c-.056 0-.103.045-.103.103l-.224 8.835c-.008.057.038.104.094.104h1.186c.056 0 .103-.045.103-.103l.224-8.835c.008-.057-.038-.104-.094-.104H5.382zm2.112-1.127c-.056 0-.103.045-.103.103l-.15 9.96c-.008.057.038.104.094.104h1.186c.056 0 .103-.045.103-.103l.15-9.96c.008-.057-.038-.104-.094-.104H7.494zm2.112-.66c-.056 0-.103.045-.103.103l-.078 10.62c0 .057.046.103.103.103h1.186c.056 0 .103-.045.103-.103l.078-10.62c0-.057-.046-.103-.103-.103H9.606zm13.197 3.513c-.58 0-1.136.143-1.626.398C20.73 9.4 18.57 7.5 16.02 7.5c-.53 0-1.04.08-1.52.23-.27-2.14-2.1-3.8-4.32-3.8-.18 0-.35.01-.52.03-.06.01-.1.06-.1.12l.06 14.65c0 .06.05.1.1.1h13.17c1.7 0 3.09-1.38 3.09-3.09 0-1.7-1.38-3.09-3.09-3.09z\"></path></svg></div><span class=\"font-mono text-[10px] text-signal-red uppercase font-bold\">СЛУШАТЬ →</span></div><div><h3 class=\"font-headline text-2xl text-white uppercase group-hover:text-signal-red transition-colors\">Архив SoundCloud</h3></div>",
