        "t_175": "// 服务01",
        "t_176": "视频和电影景点",
        "t_177": "高保真视听制作、广告、企业宣传片和人工智能辅助影院。",
        "t_178": "技术档案 →",
        "t_179": "// 服务02",
        "t_180": "后期制作和声音 EBU R128",
        "t_181": "混音工程、电影和 OTT 平台 (Netflix/HBO) 的母带处理以及取证音频。",
        "t_182": "// 服务 03",
        "t_183": "直播和流媒体专业版",
        "t_184": "使用 OBS/QLab 进行多媒体管理、现场直播、多机位现场表演和自动化。",
        "t_185": "// 服务 04",
        "t_186": "DJ 现场及混音",
        "t_187": "用于大格式、声音识别管理和混音的高级现场音乐会议。",
        "t_188": "// 服务05",
        "t_189": "网页开发和网页应用程序",
        "t_190": "开发自定义交互式 Web 应用程序、高性能登陆页面和 API 集成。",
        "t_191": "// 服务 06",
        "t_192": "动态图形与设计",
        "t_193": "2D/3D 动画、数字图像处理、活动图形包装和品牌设计。",
        "t_194": "// 服务 07",
        "t_195": "企业AI落地",
        "t_196": "使用生成人工智能、智能代理和合法的声音生物识别克隆实现工作流程自动化。",
        "t_197": "// 服务 08",
        "t_198": "培训与咨询",
        "t_199": "为人工智能、广播软件和项目管理团队提供量身定制的培训。",
        "t_200": "// 经审计的存储库专有软件",
        "t_201": "人工智能和原型生态系统",
        "t_202": "我们内部实验室设计的专有工具，用于优化和自动化视听后期制作和声音设计。",
        "t_203": "v1.0.0 Stable // Electron + React",
        "t_204": "<strong>模块化桌面应用程序：</strong>统一了用于本地 EBU R128 声音母带处理的大规模视频编辑、图像处理和 DAW 控制台的高级工具。",
        "t_205": "v1.0.0 Stable // FastAPI + FFmpeg",
        "t_206": "<strong>加速电影管道：</strong>加速渲染后端，用于动态注入专业 LUT (.cube)、实时色度操作和高并发转码。",
        "t_207": "v1.0.0 Stable // LLM Multimodal",
        "t_208": "<strong>商业音乐策划引擎：</strong>为零售、合成神经配音和个性化商业播放列表生成健全的身份策略。",
        "t_209": "// 作品和影片的现场展示",
        "t_210": "生成作品样本",
        "t_211": "视听项目的选择。单击任意卡或<strong>PLAY</strong>按钮即可打开具有<strong>全高保真音频</strong>的播放器。",
        "t_212": "// Instagram 卷轴（代理 IA）",
        "t_213": "[现场表演]",
        "t_214": "Instagram 卷轴",
        "t_215": "收听音频 →",
        "t_216": "美国工作🇺🇸",
        "t_217": "Acting I.A by @chus_bzn：1967 年与 John Williams 和 Walter Cronkite 合作的美学和声音设计。",
        "t_218": "格式：卷轴 9:16",
        "t_219": "播放音频 →",
